// Deathloom fork: campaign guide route (PoE1, acts 1-10).
//
// campaign-route.json is generated by tools/gen-campaign-route.py from Exile
// Leveling's route files (MIT, (c) 2025 HeartofPhos; licence in
// exile-leveling.LICENSE.txt). Regenerate it at each league start. One step per
// zone you enter; the guide moves to the next matching step when Client.txt says
// "You have entered <zone>". Quest passive points sit on the quest's hand-in line.

import ROUTE_JSON from './campaign-route.json'

export type RoutePart = string | {
  k: 'quest' | 'kill' | 'area' | 'waypoint' | 'waypoint_get' | 'trial' | 'logout' | 'dir' | 'generic' |
  'quest_text' | 'arena' | 'crafting' | 'ascend' | 'portal'
  v?: string | number
  // quest: quest id, reward offer id (quest-gems.json), passive / respec points
  id?: string
  offer?: string
  // more reward offers on the same hand-in (Mercy Mission: flask + Nessa's support gem)
  more?: string[]
  passive?: number
  respec?: number
  // quest hand-in rewards (game data): questItem (keys, books), items, gems, vendor (gems to buy after)
  rewards?: Array<'questItem' | 'items' | 'gems' | 'vendor'>
  // crafting: bench recipes found in this zone
  recipes?: string[]
}
// only: shown for one bandit choice ("BANDIT_ALIRA") or all but one ("!BANDIT_KILL")
export interface RouteTask { parts: RoutePart[], subs?: RoutePart[][], only?: string }
export interface RouteStep {
  zone: string
  areaId: string
  act: number
  town: boolean
  via: 'start' | 'enter' | 'waypoint' | 'logout'
  tasks: RouteTask[]
  only?: string
}

// Bandit choice: from the PoB build's Configuration tab (the levelling planner
// saves it here so every window's guide follows it). Default: kill all.
export type BanditFlag = 'BANDIT_KILL' | 'BANDIT_ALIRA' | 'BANDIT_KRAITYN' | 'BANDIT_OAK'
export const BANDIT_KEY = 'deathloom.bandit.v1'
export const BANDIT_LABEL: Record<BanditFlag, string> = {
  BANDIT_KILL: 'Kill all three (+1 passive)',
  BANDIT_ALIRA: 'Help Alira',
  BANDIT_KRAITYN: 'Help Kraityn',
  BANDIT_OAK: 'Help Oak'
}
export function banditFromPob (v: string | undefined): BanditFlag {
  return v === 'Alira' ? 'BANDIT_ALIRA' : v === 'Kraityn' ? 'BANDIT_KRAITYN' : v === 'Oak' ? 'BANDIT_OAK' : 'BANDIT_KILL'
}
export function loadBandit (): BanditFlag {
  try {
    const v = localStorage.getItem(BANDIT_KEY)
    return v && v in BANDIT_LABEL ? v as BanditFlag : 'BANDIT_KILL'
  } catch { return 'BANDIT_KILL' }
}
export function saveBandit (v: BanditFlag) {
  try { if (localStorage.getItem(BANDIT_KEY) !== v) localStorage.setItem(BANDIT_KEY, v) } catch {}
}
// Optional quests (A Fixture of Fate, A Dirty Job, Bestel's Epic …): shown unless switched off
export const OPTIONAL_KEY = 'deathloom.guide.optional.v1'
export function showOptional (): boolean {
  try { return localStorage.getItem(OPTIONAL_KEY) !== '0' } catch { return true }
}

export function onlyActive (only: string | undefined, bandit: BanditFlag = loadBandit(), optional: boolean = showOptional()): boolean {
  if (!only) return true
  if (only === 'OPTIONAL') return optional
  return only.startsWith('!') ? only.slice(1) !== bandit : only === bandit
}

// In route order
export const STEPS = clarifyVendorLines((ROUTE_JSON as unknown as { steps: RouteStep[] }).steps)

// Deathloom fork: the route's vendor recipe lines listed only the ingredients.
// Say what to do and what you get (checked against poedb / poewiki 14 Nov 2026).
function clarifyVendorLines (steps: RouteStep[]): RouteStep[] {
  const text = (sub: RoutePart[]) => sub.map(p => typeof p === 'string' ? p : String(p.v ?? '')).join('')
  const g = (v: string): RoutePart => ({ k: 'generic', v })
  const CLEAR: Record<string, RoutePart[]> = {
    'Vendor Quicksilver Flask + Orb of Augmentation + Normal Boots': [
      'Recipe: sell a white (normal) ', g('Boots'), ' + ', g('Quicksilver Flask'), ' + ', g('Orb of Augmentation'),
      ' to any vendor together → magic boots with 10% increased movement speed'
    ],
    'Vendor Quicksilver Flask + Orb of Augmentation + Movement Speed Boots': [
      'Already have movement speed boots? Same recipe with them → +5% more (up to 30%); their other mods are lost'
    ]
  }
  for (const st of steps) {
    for (const t of st.tasks) {
      if (!t.subs) continue
      t.subs = t.subs.map(sub => CLEAR[text(sub)] ?? sub)
    }
  }
  addActOneNotes(steps)
  return steps
}

// Deathloom fork (Gerhard, 14 Nov 2026): the route only showed The Way Forward
// at its act 2 hand-in, and logged out after Brutus without the Prisoner's
// Gate waypoint. Notes added to existing steps (no new steps, so saved guide
// positions stay valid). Checked against poewiki / poedb.
function addActOneNotes (steps: RouteStep[]) {
  const first = (area: string) => steps.find(s => s.areaId === area)
  const q = (v: string): RoutePart => ({ k: 'quest_text', v })
  first('1_1_5')?.tasks.push({
    parts: ['Quest received: ', q('The Way Forward')],
    subs: [['From Tarkleigh. It stays open until act 2 (open the seal in the Western Forest); then Bestel in Lioneye\'s Watch gives a passive point']]
  })
  const upper = first('1_1_7_2')
  const brutus = upper?.tasks.findIndex(t => t.parts.some(p => typeof p !== 'string' && p.k === 'kill' && String(p.v).startsWith('Brutus')))
  if (upper && brutus != null && brutus >= 0) {
    upper.tasks.splice(brutus + 1, 0, {
      parts: ['Walk on into ', { k: 'area', v: "Prisoner's Gate" }, ' and get its ', { k: 'waypoint_get' }],
      subs: [['The waypoint is right at the start. Then log out to Lioneye\'s Watch']]
    })
  }
  first('1_1_8')?.tasks.push({
    parts: ['The road north is sealed: ', q('The Way Forward'), ' continues in act 2']
  })
}

function stepPassives (st: RouteStep, bandit: BanditFlag): number {
  if (!onlyActive(st.only, bandit)) return 0
  let n = 0
  for (const t of st.tasks) {
    if (!onlyActive(t.only, bandit)) continue
    for (const p of t.parts) if (typeof p !== 'string' && p.passive) n += p.passive
  }
  return n
}

// Passive points from quests on the route: 24 when killing all three bandits, else 23
export function questPassivesTotal (bandit: BanditFlag = loadBandit()): number {
  return STEPS.reduce((n, st) => n + stepPassives(st, bandit), 0)
}
export const QUEST_PASSIVES = questPassivesTotal('BANDIT_KILL')

// Where the guide is (index into STEPS), shared by every window through localStorage
// (v2: the route from 1.0.33; v1 indexes were for the old hand-written route)
export const CAMPAIGN_STEP_KEY = 'deathloom.campaign-step.v2'
export function loadCampaignStep (): number {
  try { return Math.min(STEPS.length - 1, Math.max(0, Number(localStorage.getItem(CAMPAIGN_STEP_KEY)) || 0)) } catch { return 0 }
}

// Quest passive points from the steps before this one (optional quests counted
// as done; /passives in game is exact)
export function questPassivesBefore (index: number, bandit: BanditFlag = loadBandit()): number {
  return STEPS.slice(0, index).reduce((n, st) => n + stepPassives(st, bandit), 0)
}

const norm = (z: string) => z.toLowerCase().replace(/^the /, '').trim()

// Act from the area id in Client.txt ('Generating level 13 area "1_3_7"' -> 3;
// "2_6_1" -> 6). null for hideouts, maps and anything else.
export function actFromAreaCode (code: string | undefined): number | null {
  const m = code?.match(/^\d+_(\d+)_/)
  const act = m ? Number(m[1]) : NaN
  return act >= 1 && act <= 10 ? act : null
}

// Forward-only: the next matching step after the current one, so going back
// to a town or an earlier zone never moves the guide backwards. With the act
// known (from the area id) only that act's steps count, so act 1's "The Coast"
// never jumps to act 6's. Without it, only the current and the next act.
// Returns -1 when there's no forward match.
export function findStep (zone: string, current: number, act: number | null = null, bandit: BanditFlag = loadBandit()): number {
  const target = norm(zone)
  const curAct = STEPS[Math.max(0, Math.min(current, STEPS.length - 1))].act
  for (let i = Math.max(0, current + 1); i < STEPS.length; i++) {
    const s = STEPS[i]
    if (act != null ? s.act !== act : s.act > curAct + 1) continue
    if (!onlyActive(s.only, bandit)) continue
    if (norm(s.zone) !== target) continue
    // towns come up again and again: a town visit only moves the guide when the
    // route goes there next (a trip to sell doesn't skip zones)
    // Same for another act's town (back to Lioneye's Watch to hand in a quest):
    // the guide stays put instead of jumping to a later visit there
    if (s.town && i > current + 2) return -1
    return i
  }
  return -1
}

// Whether the zone is anywhere on the route (for the "not on the route" note)
export function isOnRoute (zone: string): boolean {
  const target = norm(zone)
  return STEPS.some(s => norm(s.zone) === target)
}
